-- Migration Files: public project episodes and evidence. Apply after 001 and 002.
PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE estate_source (id TEXT PRIMARY KEY, title TEXT NOT NULL, publisher TEXT NOT NULL, url TEXT NOT NULL CHECK(url LIKE 'https://%'), published_at TEXT, reviewed_at TEXT NOT NULL);
CREATE TABLE estate_project (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE estate_episode (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES estate_project(id), period_label TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Operational','Proposed','Abandoned')), opened_label TEXT, operator_name TEXT NOT NULL, notes TEXT NOT NULL, reviewed_at TEXT NOT NULL);
CREATE TABLE estate_evidence (episode_id TEXT NOT NULL REFERENCES estate_episode(id), source_id TEXT NOT NULL REFERENCES estate_source(id), PRIMARY KEY(episode_id,source_id));
CREATE TABLE estate_measure (id TEXT PRIMARY KEY, episode_id TEXT NOT NULL REFERENCES estate_episode(id), source_id TEXT NOT NULL REFERENCES estate_source(id), measure TEXT NOT NULL CHECK(measure IN ('planned_places','capacity','occupancy','spending')), value REAL, value_status TEXT NOT NULL CHECK(value_status IN ('published','derived_zero','missing')), unit TEXT NOT NULL CHECK(unit IN ('places','people','GBP')), period_label TEXT NOT NULL, basis TEXT NOT NULL, CHECK(value IS NULL OR value>=0), CHECK((value_status='missing' AND value IS NULL) OR (value_status<>'missing' AND value IS NOT NULL)));
CREATE TABLE estate_event (id INTEGER PRIMARY KEY, episode_id TEXT NOT NULL REFERENCES estate_episode(id), sequence INTEGER NOT NULL, date_label TEXT NOT NULL, event TEXT NOT NULL, UNIQUE(episode_id,sequence));
-- Future contract imports reference original notices; profit remains a separate accounts measure.
CREATE TABLE estate_contract (id TEXT PRIMARY KEY, episode_id TEXT NOT NULL REFERENCES estate_episode(id), source_id TEXT NOT NULL REFERENCES estate_source(id), notice_id TEXT NOT NULL, buyer TEXT NOT NULL, supplier TEXT NOT NULL, amount_gbp REAL CHECK(amount_gbp>=0), value_basis TEXT NOT NULL CHECK(value_basis IN ('award','ceiling','commitment','payment','modification')), period_label TEXT NOT NULL, vat_basis TEXT NOT NULL);
CREATE TABLE estate_company_profit (id TEXT PRIMARY KEY, company TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES estate_source(id), accounting_period TEXT NOT NULL, amount_gbp REAL NOT NULL, accounting_basis TEXT NOT NULL, scope TEXT NOT NULL);
PRAGMA user_version=2;
COMMIT;
